class Hotel {
    private String name;
    private int stars;

    Hotel(String name, int stars) {
        this.name = name;     // field on the left, parameter on the right
        this.stars = stars;
    }

    Hotel(String name) {
        this(name, 3);        // calls the other constructor, must be line one
    }

    Hotel copy() {
