Hotel b = new Hotel("Danube View", 4);
System.out.println(a == b);        // false, two objects
System.out.println(a.equals(b));  // true, same values

java.util.Set<Hotel> set = new java.util.HashSet<>();
set.add(a);
set.add(b);
